// /api/voice-roster.json and /api/bio-roster.json: the voice lines and bios a contributor can still translate
// (game text missing or equal to JP). Generated by tools/gen_translation_rosters.py into
// _data/processed/{voice,bio}_roster.json (gitignored; the same files the voice table and bio infobox read
// from site.data); wiki-cms validates lah-voice-tl / lah-bio-tl submissions against these (docs/CONTRIBUTOR_EDITING_PLAN.md).
// Without the generated files (a local build) both come out empty, so nothing is offered for translation.

import fs from "node:fs";

const ROSTERS = [
  { permalink: "/api/voice-roster.json", file: "_data/processed/voice_roster.json", empty: { version: "", resources: {} } },
  { permalink: "/api/bio-roster.json", file: "_data/processed/bio_roster.json", empty: { version: "", bios: {} } },
];

function readRoster({ file, empty }) {
  try {
    return JSON.parse(fs.readFileSync(file, "utf8"));
  } catch (e) {
    if (e.code === "ENOENT") return empty;
    throw e;
  }
}

export default class TranslationRosters {
  data() {
    return {
      pagination: { data: "rosterFiles", size: 1, alias: "roster" },
      rosterFiles: ROSTERS,
      permalink: (data) => data.roster.permalink,
      layout: "none",
      eleventyExcludeFromCollections: true,
    };
  }

  render(data) {
    return JSON.stringify(readRoster(data.roster));
  }
}
